  1	/**
  2	 * API client for Guitar Tone Shootout backend.
  3	 * Uses the Vite proxy configuration to forward /api requests to the backend.
  4	 *
  5	 * STORY-008: API client uses error handling utilities to normalize error responses.
  6	 * - Throws ApiError class with code, message, requestId properties
  7	 * - Sanitizes error messages before throwing
  8	 * - Preserves original response for debugging
  9	 */
 10	
 11	import { getErrorMessage, extractErrorCode } from './error-handling';
 12	
 13	const API_BASE = '/api/v1';
 14	
 15	/**
 16	 * Shape of error responses from the API.
 17	 * Handles multiple formats for backwards compatibility.
 18	 */
 19	interface ApiErrorResponse {
 20	  detail?: string;
 21	  message?: string;
 22	  code?: string;
 23	  request_id?: string;
 24	  error?: {
 25	    message?: string;
 26	    code?: string;
 27	  };
 28	}
 29	
 30	/**
 31	 * Custom error class for API errors.
 32	 * Carries error code, sanitized message, and request ID for support reference.
 33	 *
 34	 * @example
 35	 * ```ts
 36	 * try {
 37	 *   await api.get('/protected-resource');
 38	 * } catch (error) {
 39	 *   if (error instanceof ApiError) {
 40	 *     console.log(error.code);      // 'AUTH_001'
 41	 *     console.log(error.message);   // 'Authentication required'
 42	 *     console.log(error.requestId); // 'req-123-456'
 43	 *   }
 44	 * }
 45	 * ```
 46	 */
 47	export class ApiError extends Error {
 48	  /** Error code in CATEGORY_NNN format (e.g., AUTH_001, VAL_002) or null */
 49	  public readonly code: string | null;
 50	
 51	  /** Request ID for support reference and log correlation */
 52	  public readonly requestId: string | null;
 53	
 54	  /** Original error response from the API (for debugging in dev mode) */
 55	  public readonly originalResponse: unknown;
 56	
 57	  constructor(
 58	    message: string,
 59	    code: string | null = null,
 60	    requestId: string | null = null,
 61	    originalResponse: unknown = null
 62	  ) {
 63	    super(message);
 64	    this.name = 'ApiError';
 65	    this.code = code;
 66	    this.requestId = requestId;
 67	    this.originalResponse = originalResponse;
 68	
 69	    // Maintain proper stack trace in V8 environments
 70	    if (Error.captureStackTrace) {
 71	      Error.captureStackTrace(this, ApiError);
 72	    }
 73	  }
 74	}
 75	
 76	/**
 77	 * Extract request_id from error response.
 78	 * Handles both flat and nested error shapes.
 79	 */
 80	function extractRequestId(errorData: ApiErrorResponse): string | null {
 81	  // Direct request_id (flat format or alongside nested error)
 82	  if (typeof errorData.request_id === 'string' && errorData.request_id.trim()) {
 83	    return errorData.request_id;
 84	  }
 85	  return null;
 86	}
 87	
 88	class ApiClient {
 89	  private async request<T>(
 90	    path: string,
 91	    options: RequestInit = {}
 92	  ): Promise<T> {
 93	    const url = `${API_BASE}${path}`;
 94	    const headers: HeadersInit = {
 95	      'Content-Type': 'application/json',
 96	      ...options.headers,
 97	    };
 98	
 99	    const response = await fetch(url, {
100	      ...options,
101	      headers,
102	      credentials: 'include', // Include cookies for session auth
103	    });
104	
105	    if (!response.ok) {
106	      // Try to parse JSON error response, fallback to generic HTTP error
107	      const errorData: ApiErrorResponse = await response.json().catch(() => ({
108	        detail: `HTTP ${response.status}: ${response.statusText}`,
109	      }));
110	
111	      // Extract and sanitize error message using error handling utilities
112	      const sanitizedMessage = getErrorMessage(errorData);
113	
114	      // Extract error code (returns null if not present or invalid format)
115	      const errorCode = extractErrorCode(errorData);
116	
117	      // Extract request_id for support reference
118	      const requestId = extractRequestId(errorData);
119	
120	      // Throw ApiError with sanitized message, code, request_id, and original response
121	      throw new ApiError(sanitizedMessage, errorCode, requestId, errorData);
122	    }
123	
124	    // Handle 204 No Content
125	    if (response.status === 204) {
126	      return undefined as T;
127	    }
128	
129	    return response.json();
130	  }
131	
132	  get<T>(path: string): Promise<T> {
133	    return this.request<T>(path, { method: 'GET' });
134	  }
135	
136	  post<T>(path: string, data?: unknown): Promise<T> {
137	    return this.request<T>(path, {
138	      method: 'POST',
139	      body: data ? JSON.stringify(data) : undefined,
140	    });
141	  }
142	
143	  put<T>(path: string, data: unknown): Promise<T> {
144	    return this.request<T>(path, {
145	      method: 'PUT',
146	      body: JSON.stringify(data),
147	    });
148	  }
149	
150	  patch<T>(path: string, data: unknown): Promise<T> {
151	    return this.request<T>(path, {
152	      method: 'PATCH',
153	      body: JSON.stringify(data),
154	    });
155	  }
156	
157	  delete<T>(path: string): Promise<T> {
158	    return this.request<T>(path, { method: 'DELETE' });
159	  }
160	}
